namespace sv_0989bd10b6e74ae5be73eea16030ff8c;

public enum Theme
{
    Light,
    Dark,
    System
}

public class ThemeInfo
{
    public Theme Theme { get; set; } = Theme.Light;
    public string AccentColor { get; set; } = "#0d6efd";
}

@rendermode InteractiveServer
@inject CascadingValueSource<ThemeInfo> ThemeSource

<span class="theme-indicator" style="color: @(Theme?.AccentColor ?? "#0d6efd");">
    @GetThemeIcon() @(Theme?.Theme.ToString() ?? "Light")
</span>

<button class="btn btn-sm btn-outline-secondary ms-2" @onclick="CycleTheme" title="Toggle theme">
    🔄
</button>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private async Task CycleTheme()
    {
        if (Theme is null) return;

        Theme.Theme = Theme.Theme switch
        {
            Theme.Light => Theme.Dark,
            Theme.Dark => Theme.System,
            Theme.System => Theme.Light,
            _ => Theme.Light
        };

        await ThemeSource.NotifyChangedAsync();
    }

    private string GetThemeIcon() => Theme?.Theme switch
    {
        Theme.Light => "☀️",
        Theme.Dark => "🌙",
        Theme.System => "💻",
        _ => "☀️"
    };
}

@page "/settings"
@rendermode InteractiveServer
@inject CascadingValueSource<ThemeInfo> ThemeSource

<PageTitle>Settings</PageTitle>

<h3>User Preferences</h3>

<div class="card mt-3" style="max-width: 500px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="mb-3">
            <label class="form-label">Color Mode</label>
            <select class="form-select" value="@selectedTheme" @onchange="OnThemeChanged">
                <option value="Light">☀️ Light</option>
                <option value="Dark">🌙 Dark</option>
                <option value="System">💻 System</option>
            </select>
        </div>

        <div class="mb-3">
            <label class="form-label">Accent Color</label>
            <div class="d-flex align-items-center gap-2">
                <input type="color" class="form-control form-control-color"
                       value="@accentColor" @onchange="OnAccentColorChanged" />
                <span style="color: @accentColor; font-weight: bold;">@accentColor</span>
            </div>
        </div>

        <div class="alert alert-info mt-3">
            <strong>Current:</strong> @Theme?.Theme mode with accent
            <span style="color: @Theme?.AccentColor;">■ @Theme?.AccentColor</span>
        </div>
    </div>
</div>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private string selectedTheme = "Light";
    private string accentColor = "#0d6efd";

    protected override void OnParametersSet()
    {
        if (Theme is not null)
        {
            selectedTheme = Theme.Theme.ToString();
            accentColor = Theme.AccentColor;
        }
    }

    private async Task OnThemeChanged(ChangeEventArgs e)
    {
        if (Theme is null || e.Value is not string val) return;

        if (Enum.TryParse<Theme>(val, out var parsed))
        {
            Theme.Theme = parsed;
            selectedTheme = val;
            await ThemeSource.NotifyChangedAsync();
        }
    }

    private async Task OnAccentColorChanged(ChangeEventArgs e)
    {
        if (Theme is null || e.Value is not string val) return;

        Theme.AccentColor = val;
        accentColor = val;
        await ThemeSource.NotifyChangedAsync();
    }
}

